import numpy as np
NAME = '길게 꾸준히 오른 곳 + 닷새 눌림'
def score(F):
    L = F.zcs(F.ret(250) - F.ret(20)) - 0.5 * F.zcs(F.vol(120))
    return F.zcs(L) + np.nan_to_num(F.zcs(-F.rel(5)))

